// Generates docs/process-map.md and docs/import.md from the code, so docs cannot drift.
// Run: npm run docs
import { writeFileSync, mkdirSync } from "node:fs";
import ExcelJS from "exceljs";
import { PROCESS_MERMAID, PROCESS_NOTES } from "../src/lib/process-map";
import { IMPORT_FIELDS, IGNORED_HEADERS } from "../src/lib/import/mapping";

mkdirSync("docs", { recursive: true });

writeFileSync(
  "docs/process-map.md",
  `# Export process map

<!-- Generated by \`npm run docs\` from src/lib/process-map.ts. Do not edit by hand. -->

Ocean export flow at NNR Global Logistics, from booking request to arrival. Also shown in the app at \`/process\`.
Italic labels are the shipment status after each step.

\`\`\`mermaid
${PROCESS_MERMAID}
\`\`\`

${PROCESS_NOTES.map((n) => `- ${n}`).join("\n")}
`,
);

const rows = IMPORT_FIELDS.map((f) => {
  const headers = f.headers.map((h) => `\`${h}\``).join(", ");
  const req = "required" in f && f.required ? "yes" : "";
  const note = "note" in f ? f.note : "";
  return `| ${f.key} | ${headers} | ${req} | ${note} |`;
}).join("\n");

writeFileSync(
  "docs/import.md",
  `# Spreadsheet import (one-time)

<!-- Generated by \`npm run docs\` from src/lib/import/mapping.ts. Do not edit by hand. -->

Supervisors import the existing monitoring spreadsheet at **Import** (\`/admin/import\`). There is no
column-mapping screen: the first worksheet's first row must use the headers below (any one spelling
per field; case, spaces and punctuation are ignored). Other columns are listed as "ignored" and skipped.

## How it works

1. Upload the \`.xlsx\` with **Check only** ticked: nothing is saved; you see how many rows are valid and every problem.
2. Untick it and import: valid rows become shipments (source \`IMPORT\`), invalid rows are listed with the reason.
A ready-to-fill template with these headers is in \`docs/import-template.xlsx\`.

3. Download **rows to fix** (an Excel file with an \`Error\` column and the original values), correct them, and upload that file.
   Rows already imported are skipped (same HBL No., same Job No., or same old booking no.), so re-uploading is safe.

## Columns

| Field | Accepted headers | Required | Notes |
|---|---|---|---|
${rows}

Ignored on purpose (calculated by the app): ${IGNORED_HEADERS.map((h) => `\`${h}\``).join(", ")}.

## Values

- **Dates:** real Excel date cells, or text \`16-Oct-2026 09:00\` / \`2026-10-16 09:00\`, read as Asia/Manila time.
  Slash dates such as \`10/11/2026\` are rejected because day/month order is ambiguous.
- **Shipment date for reports:** the earliest of requested pick-up, FSI cut-off and ETD, so old shipments
  count in their own month. New Job Nos. use that month too.
- **Status** is recalculated from the dates (e.g. an ATD makes it DEPARTED); only "Cancelled" and "Closed" are read.
- **Arrastre Paid** on imported rows needs no proof file (old records); new payments in the app still require proof.
- Every row is checked with the same rules as the shipment form (e.g. ETA after ETD, FCL needs containers),
  plus: ATA needs ATD, arrastre cannot be paid by NNR when the shipper pays.
- Max ${5000} rows per file.
`,
);

// Template with the preferred header spelling and two example rows.
async function template() {
  const wb = new ExcelJS.Workbook();
  const ws = wb.addWorksheet("Monitoring");
  ws.addRow(IMPORT_FIELDS.map((f) => f.headers[0]));
  ws.getRow(1).font = { bold: true };
  const example: Record<string, string> = {
    jobNo: "", hblNo: "", shipper: "Luzon Coco Products Inc.", destination: "USLAX Los Angeles", pod: "USLGB Long Beach",
    cargo: "2x40HC + 1x20", carrier: "Maersk", bookingRef: "MAEU240001", requestedPickup: "20-Oct-2026 09:00",
    fsiCutoff: "22-Oct-2026 17:00", preadviseCutoff: "23-Oct-2026 12:00", etd: "25-Oct-2026 08:00", arrastreBy: "NNR", cs: "cs1@nnr.test",
  };
  const lcl: Record<string, string> = {
    jobNo: "B-1234", shipper: "Pinoy Dried Mango Co.", destination: "SGSIN Singapore", cargo: "LCL 6 PALLET",
    requestedPickup: "2026-10-21 10:00", declaration: "FILED", arrastreBy: "SHIPPER", remarks: "Old booking from the spreadsheet",
  };
  for (const r of [example, lcl]) ws.addRow(IMPORT_FIELDS.map((f) => r[f.key] ?? ""));
  ws.columns.forEach((c) => (c.width = 20));
  await wb.xlsx.writeFile("docs/import-template.xlsx");
}

template().then(() => console.log("Wrote docs/process-map.md, docs/import.md and docs/import-template.xlsx"));
